from __future__ import annotations

import hashlib
import json
import time
from datetime import UTC, datetime
from decimal import Decimal
from pathlib import Path
from typing import Any

from packages.common.pg_native import PostgresMigration, apply_schema_migrations, connect_postgres
from .defaults import DEFAULT_SYMBOLS, DEFAULT_TEMPLATES
from .models import PublishMode, ReferenceMetrics, SymbolConfig, SymbolState, TickerQuote

SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS settings(key text PRIMARY KEY,value text NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS symbol_config(symbol text PRIMARY KEY,display_name text NOT NULL,threshold text NOT NULL,price_precision integer NOT NULL,unit text NOT NULL,enabled boolean NOT NULL DEFAULT true,updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS templates(template_key text PRIMARY KEY,label text NOT NULL,title_template text NOT NULL,body_template text NOT NULL,updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS symbol_state(symbol text NOT NULL,mode text NOT NULL,initialized boolean NOT NULL DEFAULT false,last_price text,last_quote_at bigint,disarmed_levels jsonb NOT NULL DEFAULT '[]',market_status text,next_open_at bigint,last_success_at bigint,last_error text,updated_at bigint NOT NULL,PRIMARY KEY(symbol,mode));
CREATE TABLE IF NOT EXISTS price_samples(symbol text NOT NULL,observed_at bigint NOT NULL,price text NOT NULL,PRIMARY KEY(symbol,observed_at));
CREATE INDEX IF NOT EXISTS idx_gate_market_samples_time ON price_samples(symbol,observed_at);
CREATE TABLE IF NOT EXISTS trigger_events(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,event_key text NOT NULL UNIQUE,mode text NOT NULL,symbol text NOT NULL,direction text NOT NULL,trigger_level text NOT NULL,current_price text NOT NULL,reference_kind text,reference_price text,window_high text,window_low text,change_percent text,template_key text,status text NOT NULL,title text,content text,push_status_code integer,push_response text,error text,odaily_external_error_counted integer NOT NULL DEFAULT 0,observed_at bigint NOT NULL,created_at bigint NOT NULL,updated_at bigint NOT NULL);
CREATE INDEX IF NOT EXISTS idx_gate_market_events_recent ON trigger_events(created_at DESC,id DESC);
CREATE TABLE IF NOT EXISTS alert_state(alert_key text PRIMARY KEY,active boolean NOT NULL DEFAULT false,last_sent_at bigint,last_message text,updated_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS legacy_symbol_state(mode text NOT NULL,symbol text NOT NULL,payload jsonb NOT NULL,archived_at bigint NOT NULL,PRIMARY KEY(mode,symbol));
"""
CHECKSUM = hashlib.sha256(SCHEMA_SQL.encode()).hexdigest()


class PostgresGateMarketStore:
    def __init__(self, path: Path, *, initialize: bool = True) -> None:
        self.path = path
        if initialize:
            self.initialize()

    def initialize(self) -> None:
        self.initialize_schema()
        with connect_postgres(schema="gate", application_name="odaily-gate-market-migrate") as conn:
            now=int(time.time())
            for key,value in (("mode","backend"),("poll_interval_seconds","60")):
                conn.execute("INSERT INTO settings(key,value,updated_at) VALUES(%s,%s,%s) ON CONFLICT(key) DO NOTHING",(key,value,now))
            for item in DEFAULT_SYMBOLS:
                conn.execute("INSERT INTO symbol_config(symbol,display_name,threshold,price_precision,unit,enabled,updated_at) VALUES(%s,%s,%s,%s,%s,true,%s) ON CONFLICT(symbol) DO NOTHING",(item.symbol,item.display_name,item.threshold,item.price_precision,item.unit,now))
            for key,label,title,body in DEFAULT_TEMPLATES:
                conn.execute("INSERT INTO templates(template_key,label,title_template,body_template,updated_at) VALUES(%s,%s,%s,%s,%s) ON CONFLICT(template_key) DO NOTHING",(key,label,title,body,now))
            self._migrate_modes(conn,now)

    @staticmethod
    def initialize_schema() -> None:
        with connect_postgres(schema="gate", application_name="odaily-gate-market-migrate") as conn:
            apply_schema_migrations(conn, schema="gate", component="gate_market", migrations=(PostgresMigration(1,"gate market persistence",CHECKSUM,lambda c:c.execute(SCHEMA_SQL)),PostgresMigration(2,"Gate external error counter",hashlib.sha256(b"gate.trigger_events.odaily_external_error_counted.v2").hexdigest(),lambda c:c.execute("ALTER TABLE trigger_events ADD COLUMN IF NOT EXISTS odaily_external_error_counted integer NOT NULL DEFAULT 0"))))

    @staticmethod
    def _migrate_modes(conn, now: int) -> None:
        rows=conn.execute("SELECT DISTINCT symbol FROM symbol_state WHERE mode<>'shared'").fetchall()
        for item in rows:
            symbol=item["symbol"]
            conn.execute("INSERT INTO legacy_symbol_state(mode,symbol,payload,archived_at) SELECT mode,symbol,to_jsonb(symbol_state),%s FROM symbol_state WHERE symbol=%s AND mode<>'shared' ON CONFLICT(mode,symbol) DO NOTHING",(now,symbol))
            conn.execute("""INSERT INTO symbol_state(symbol,mode,initialized,last_price,last_quote_at,disarmed_levels,market_status,next_open_at,last_success_at,last_error,updated_at)
              SELECT symbol,'shared',initialized,last_price,last_quote_at,
                (SELECT COALESCE(jsonb_agg(DISTINCT v::int ORDER BY v::int),'[]'::jsonb) FROM symbol_state old CROSS JOIN LATERAL jsonb_array_elements_text(old.disarmed_levels) v WHERE old.symbol=%s AND old.mode<>'shared'),
                market_status,next_open_at,last_success_at,last_error,%s FROM symbol_state WHERE symbol=%s AND mode<>'shared' ORDER BY initialized DESC,updated_at DESC LIMIT 1
              ON CONFLICT(symbol,mode) DO NOTHING""",(symbol,now,symbol))
            conn.execute("DELETE FROM symbol_state WHERE symbol=%s AND mode<>'shared'",(symbol,))

    def _one(self,sql,params=()):
        with connect_postgres(schema="gate",application_name="odaily-gate-market") as c:return c.execute(sql,params).fetchone()
    def get_mode(self)->PublishMode:
        row=self._one("SELECT value FROM settings WHERE key='mode'"); value=str(row['value'] if row else 'backend')
        if value not in {'backend','live'}: raise ValueError(f"Invalid Gate market mode: {value}")
        return value
    def set_mode(self,mode:str)->PublishMode:
        if mode not in {'backend','live'}:raise ValueError('mode must be backend or live')
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:c.execute("INSERT INTO settings VALUES('mode',%s,%s) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at",(mode,int(time.time())))
        return mode
    def poll_interval_seconds(self)->int:
        row=self._one("SELECT value FROM settings WHERE key='poll_interval_seconds'");return max(10,int(row['value'] if row else 60))
    def list_symbol_configs(self)->list[SymbolConfig]:
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:rows=c.execute("SELECT * FROM symbol_config ORDER BY symbol").fetchall()
        return [SymbolConfig(str(r['symbol']),str(r['display_name']),str(r['threshold']),int(r['price_precision']),str(r['unit']),bool(r['enabled'])) for r in rows]
    def get_symbol_config(self,symbol:str)->SymbolConfig:
        normalized=symbol.strip().upper(); item=next((x for x in self.list_symbol_configs() if x.symbol==normalized),None)
        if item is None:raise ValueError(f'Unknown Gate market symbol: {normalized}')
        return item
    def set_threshold(self,symbol:str,threshold_text:str)->SymbolConfig:
        normalized=symbol.strip().upper(); value=Decimal(threshold_text)
        if value<=0:raise ValueError('threshold must be positive')
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:
            with c.transaction():
                changed=c.execute("UPDATE symbol_config SET threshold=%s,updated_at=%s WHERE symbol=%s",(threshold_text.strip(),int(time.time()),normalized)).rowcount
                if not changed:raise ValueError(f'Unknown Gate market symbol: {normalized}')
                c.execute("DELETE FROM symbol_state WHERE symbol=%s",(normalized,))
        return self.get_symbol_config(normalized)
    def templates(self)->dict[str,tuple[str,str]]:
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:rows=c.execute("SELECT template_key,title_template,body_template FROM templates").fetchall()
        return {str(r['template_key']):(str(r['title_template']),str(r['body_template'])) for r in rows}
    def get_state(self,symbol:str,mode:PublishMode)->SymbolState:
        r=self._one("SELECT * FROM symbol_state WHERE symbol=%s AND mode='shared'",(symbol,))
        if r is None:return SymbolState(symbol=symbol,mode=mode)
        levels=r['disarmed_levels']; levels=json.loads(levels) if isinstance(levels,str) else levels
        return SymbolState(symbol,mode,bool(r['initialized']),Decimal(r['last_price']) if r['last_price'] is not None else None,r['last_quote_at'],{int(x) for x in levels},r['market_status'],r['next_open_at'],r['last_success_at'],r['last_error'])
    def add_samples(self,symbol:str,points:list[tuple[int,Decimal]])->None:
        if not points:return
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:c.cursor().executemany("INSERT INTO price_samples VALUES(%s,%s,%s) ON CONFLICT(symbol,observed_at) DO UPDATE SET price=excluded.price",[(symbol,t,str(p)) for t,p in points])
    def recent_sample_count(self,symbol:str,since:int)->int:
        r=self._one("SELECT count(*) n FROM price_samples WHERE symbol=%s AND observed_at>=%s",(symbol,since));return int(r['n'])
    def reference_metrics(self,*,symbol:str,quote:TickerQuote)->ReferenceMetrics|None:
        target=quote.observed_at-86400
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:
            ref=c.execute("SELECT observed_at,price FROM price_samples WHERE symbol=%s AND observed_at<=%s ORDER BY observed_at DESC LIMIT 1",(symbol,target)).fetchone()
            if ref and target-int(ref['observed_at'])<=3600:
                ex=c.execute("SELECT min(price::numeric) low,max(price::numeric) high FROM price_samples WHERE symbol=%s AND observed_at>=%s",(symbol,target)).fetchone()
                if ex['low'] is not None:return ReferenceMetrics('rolling_24h',Decimal(ref['price']),Decimal(ex['high']),Decimal(ex['low']))
        if quote.previous_close:return ReferenceMetrics('previous_session',quote.previous_close,quote.high or quote.price,quote.low or quote.price)
        if quote.today_open:return ReferenceMetrics('since_open',quote.today_open,quote.high or quote.price,quote.low or quote.price)
        return None
    def save_state_and_event(self,state:SymbolState,*,event:dict[str,Any]|None=None)->int|None:
        now=int(time.time())
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:
            with c.transaction():
                c.execute("""INSERT INTO symbol_state VALUES(%s,'shared',%s,%s,%s,%s,%s,%s,%s,%s,%s) ON CONFLICT(symbol,mode) DO UPDATE SET initialized=excluded.initialized,last_price=excluded.last_price,last_quote_at=excluded.last_quote_at,disarmed_levels=excluded.disarmed_levels,market_status=excluded.market_status,next_open_at=excluded.next_open_at,last_success_at=excluded.last_success_at,last_error=excluded.last_error,updated_at=excluded.updated_at""",(state.symbol,state.initialized,str(state.last_price) if state.last_price is not None else None,state.last_quote_at,json.dumps(sorted(state.disarmed_levels)),state.market_status,state.next_open_at,state.last_success_at,state.last_error,now))
                if event is None:return None
                r=c.execute("""INSERT INTO trigger_events(event_key,mode,symbol,direction,trigger_level,current_price,reference_kind,reference_price,window_high,window_low,status,observed_at,created_at,updated_at)
                 VALUES(%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) ON CONFLICT(event_key) DO NOTHING RETURNING id""",(event['event_key'],state.mode,state.symbol,event['direction'],event['trigger_level'],event['current_price'],event.get('reference_kind'),event.get('reference_price'),event.get('window_high'),event.get('window_low'),event.get('status','pending'),event['observed_at'],now,now)).fetchone()
                return int(r['id']) if r else None
    def mark_event(self,event_id:int,*,status:str,template_key:str|None=None,change_percent:Decimal|None=None,title:str|None=None,content:str|None=None,push_status_code:int|None=None,push_response:str|None=None,error:str|None=None)->None:
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:c.execute("UPDATE trigger_events SET status=%s,template_key=%s,change_percent=%s,title=%s,content=%s,push_status_code=%s,push_response=%s,error=%s,updated_at=%s WHERE id=%s",(status,template_key,str(change_percent) if change_percent is not None else None,title,content,push_status_code,push_response,error,int(time.time()),event_id))
    def record_fetch_error(self,symbol:str,mode:PublishMode,message:str)->SymbolState:
        state=self.get_state(symbol,mode);state.last_error=message[:1000];self.save_state_and_event(state);return state
    def prune(self,*,sample_retention_hours:int=48,event_limit:int=100)->None:
        cutoff=int(time.time())-sample_retention_hours*3600
        with connect_postgres(schema='gate',application_name='odaily-gate-market-retention') as c:
            with c.transaction():c.execute("DELETE FROM price_samples WHERE observed_at<%s",(cutoff,));c.execute("DELETE FROM trigger_events WHERE id NOT IN (SELECT id FROM trigger_events ORDER BY created_at DESC,id DESC LIMIT %s)",(event_limit,))
    def should_send_alert(self,alert_key:str,message:str,dedup_seconds:int)->bool:
        now=int(time.time())
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:
            with c.transaction():
                c.execute("SELECT pg_advisory_xact_lock(hashtext(%s))",(f"gate-alert:{alert_key}",))
                row=c.execute("SELECT active,last_sent_at FROM alert_state WHERE alert_key=%s FOR UPDATE",(alert_key,)).fetchone()
                allowed=row is None or not row['active'] or row['last_sent_at'] is None or now-int(row['last_sent_at'])>=dedup_seconds
                if allowed:c.execute("INSERT INTO alert_state(alert_key,active,last_sent_at,last_message,updated_at) VALUES(%s,true,%s,%s,%s) ON CONFLICT(alert_key) DO UPDATE SET active=true,last_sent_at=excluded.last_sent_at,last_message=excluded.last_message,updated_at=excluded.updated_at",(alert_key,now,message[:1000],now))
                return allowed
    def recover_alert(self,alert_key:str)->bool:
        with connect_postgres(schema='gate',application_name='odaily-gate-market') as c:return bool(c.execute("UPDATE alert_state SET active=false,updated_at=%s WHERE alert_key=%s AND active=true",(int(time.time()),alert_key)).rowcount)
    def dashboard(self)->dict[str,Any]:
        mode=self.get_mode()
        with connect_postgres(schema='gate',application_name='odaily-gate-market-dashboard') as c:
            settings={str(r['key']):str(r['value']) for r in c.execute("SELECT key,value FROM settings").fetchall()}
            templates=[dict(r) for r in c.execute("SELECT * FROM templates ORDER BY template_key").fetchall()]
            rows=c.execute("SELECT sc.*,s.initialized,s.last_price,s.last_quote_at,s.disarmed_levels,s.market_status,s.next_open_at,s.last_success_at,s.last_error FROM symbol_config sc LEFT JOIN symbol_state s ON s.symbol=sc.symbol AND s.mode='shared' ORDER BY sc.symbol").fetchall()
            events=[dict(r) for r in c.execute("SELECT * FROM trigger_events ORDER BY created_at DESC,id DESC LIMIT 100").fetchall()]
        for row in rows:
            row['enabled']=bool(row['enabled']);row['initialized']=bool(row['initialized'])
            for k in ('last_quote_at','next_open_at','last_success_at'):row[k]=datetime.fromtimestamp(row[k],UTC).isoformat() if row[k] else None
        for group in (templates,events):
            for row in group:
                for k in ('updated_at','observed_at','created_at'):
                    if k in row and row[k] is not None:row[k]=datetime.fromtimestamp(row[k],UTC).isoformat()
        return {'mode':mode,'poll_interval_seconds':int(settings.get('poll_interval_seconds','60')),'database_path':f'postgres:{self.path}','symbols':rows,'templates':templates,'recent_events':events,'generated_at':datetime.now(UTC).isoformat()}


__all__=['PostgresGateMarketStore','SCHEMA_SQL']
